import json
import subprocess
import logging
import re
from datetime import datetime

logger = logging.getLogger(__name__)

class IoTMessageHandler:
    """Handles incoming MQTT messages from IoT sensor fleet.
    Supports firmware diagnostics and remote health checks."""

    ALLOWED_DIAGNOSTICS = ['temperature', 'humidity', 'pressure', 'battery']

    def __init__(self, device_registry):
        self.device_registry = device_registry
        self.message_log = []

    def validate_device_id(self, device_id):
        """Validate device ID format: alphanumeric with dashes, 8-36 chars."""
        pattern = r'^[a-zA-Z0-9\-]{8,36}$'
        return bool(re.match(pattern, device_id))

    def sanitize_metric_name(self, metric):
        """Basic sanitization for metric names."""
        # Strip whitespace and convert to lowercase
        return metric.strip().lower()

    def handle_message(self, topic, payload_raw):
        """Process incoming MQTT message from IoT device."""
        try:
            payload = json.loads(payload_raw)
        except json.JSONDecodeError:
            logger.error("Invalid JSON payload received")
            return {"status": "error", "reason": "invalid_json"}

        device_id = payload.get("device_id", "")
        if not self.validate_device_id(device_id):
            logger.warning(f"Invalid device_id format: {device_id}")
            return {"status": "error", "reason": "invalid_device_id"}

        msg_type = payload.get("type", "")

        if msg_type == "telemetry":
            return self._handle_telemetry(device_id, payload)
        elif msg_type == "diagnostic":
            return self._handle_diagnostic(device_id, payload)
        elif msg_type == "firmware_check":
            return self._handle_firmware_check(device_id, payload)
        else:
            return {"status": "error", "reason": "unknown_message_type"}

    def _handle_telemetry(self, device_id, payload):
        """Store telemetry data from device sensors."""
        metrics = payload.get("metrics", {})
        timestamp = payload.get("timestamp", datetime.utcnow().isoformat())

        for metric_name, value in metrics.items():
            sanitized = self.sanitize_metric_name(metric_name)
            if sanitized in self.ALLOWED_DIAGNOSTICS:
                self.message_log.append({
                    "device": device_id,
                    "metric": sanitized,
                    "value": value,
                    "ts": timestamp
                })

        return {"status": "ok", "processed": len(metrics)}

    def _handle_diagnostic(self, device_id, payload):
        """Run diagnostic command for device health monitoring.
        Uses device-specific diagnostic scripts stored locally."""
        diag_type = payload.get("diagnostic_type", "")
        target_interface = payload.get("interface", "eth0")

        # Validate diagnostic type against allowlist
        if diag_type not in ["network", "storage", "cpu", "memory"]:
            return {"status": "error", "reason": "invalid_diagnostic_type"}

        # Build diagnostic command - interface parameter used for network diags
        if diag_type == "network":
            # Run network diagnostic on specified interface
            cmd = f"/opt/iot-platform/diagnostics/net_check.sh {target_interface}"
        elif diag_type == "storage":
            cmd = "/opt/iot-platform/diagnostics/storage_check.sh"
        elif diag_type == "cpu":
            cmd = "/opt/iot-platform/diagnostics/cpu_check.sh"
        else:
            cmd = "/opt/iot-platform/diagnostics/mem_check.sh"

        try:
            result = subprocess.run(
                cmd,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )
            return {
                "status": "ok",
                "device_id": device_id,
                "diagnostic": diag_type,
                "output": result.stdout[:1024],
                "exit_code": result.returncode
            }
        except subprocess.TimeoutExpired:
            return {"status": "error", "reason": "diagnostic_timeout"}

    def _handle_firmware_check(self, device_id, payload):
        """Check firmware version against registry."""
        current_version = payload.get("firmware_version", "0.0.0")
        registered = self.device_registry.get(device_id, {})
        latest = registered.get("latest_firmware", "0.0.0")

        return {
            "status": "ok",
            "update_available": current_version != latest,
            "latest_version": latest
        }
